#region Using

using System;
using System.Data;
using System.Collections;
using DCore;

#endregion

namespace InformationWebObject
{
    /// <summary>
    /// Đăng ký tư vấn tiêm chủng - trang Tiêm Chủng Tâm Đức
    /// </summary>
    public partial class INFO_TiemChungRegister
    {
        #region Member Variables

        private int? intTiemChungRegisterID = null;
        private string strFullName = null;
        private string strPhone = null;
        private string strEmail = null;
        private string strMessage = null;
        private byte? bytStatus = null;
        private string strClientIP = null;
        private DateTime? dtmCreatedDate = null;
