            set { objErrorException = value; }
        }

        #endregion

        #region Methods

        public bool Parse(IDataReader reader)
        {
            try
            {
                for (int i = 0; i < reader.FieldCount; i++)
                {
                    if (reader.GetName(i).ToUpper().Equals(C_TiemChungRegisterID.ToUpper()) && !Convert.IsDBNull(reader[C_TiemChungRegisterID])) this.intTiemChungRegisterID = Convert.ToInt32(reader[C_TiemChungRegisterID]);
                    if (reader.GetName(i).ToUpper().Equals(C_FullName.ToUpper()) && !Convert.IsDBNull(reader[C_FullName])) this.strFullName = Convert.ToString(reader[C_FullName]);
                    if (reader.GetName(i).ToUpper().Equals(C_Phone.ToUpper()) && !Convert.IsDBNull(reader[C_Phone])) this.strPhone = Convert.ToString(reader[C_Phone]);
                    if (reader.GetName(i).ToUpper().Equals(C_Email.ToUpper()) && !Convert.IsDBNull(reader[C_Email])) this.strEmail = Convert.ToString(reader[C_Email]);
                    if (reader.GetName(i).ToUpper().Equals(C_Message.ToUpper()) && !Convert.IsDBNull(reader[C_Message])) this.strMessage = Convert.ToString(reader[C_Message]);
                    if (reader.GetName(i).ToUpper().Equals(C_Status.ToUpper()) && !Convert.IsDBNull(reader[C_Status])) this.bytStatus = Convert.ToByte(reader[C_Status]);
                    if (reader.GetName(i).ToUpper().Equals(C_ClientIP.ToUpper()) && !Convert.IsDBNull(reader[C_ClientIP])) this.strClientIP = Convert.ToString(reader[C_ClientIP]);
                    if (reader.GetName(i).ToUpper().Equals(C_CreatedDate.ToUpper()) && !Convert.IsDBNull(reader[C_CreatedDate])) this.dtmCreatedDate = Convert.ToDateTime(reader[C_CreatedDate]);
                    if (reader.GetName(i).ToUpper().Equals(C_IsDeleted.ToUpper()) && !Convert.IsDBNull(reader[C_IsDeleted])) this.bolIsDeleted = Convert.ToBoolean(reader[C_IsDeleted]);
                }
