                objIData.CreateNewStoredProcedure("INFO_TiemChungRegister_GET");
                objIData.AddParameter(P_TiemChungRegisterID, this.intTiemChungRegisterID);
                IDataReader reader = objIData.ExecStoreToDataReader();
                if (reader.Read())
                {
                    if (Parse(reader))
