using System;
using System.Configuration;
using System.Net.Mail;
using System.Text;
using System.Text.RegularExpressions;
using System.Web.UI;
using InformationWebObject;

namespace InformationWeb.Controls.Information.TiemChung
{
    /// <summary>
    /// Trang Tiêm Chủng - form đăng ký tư vấn.
    /// Luồng: validate -> lưu INFO_TiemChungRegister -> gửi mail admin + mail xác nhận khách.
    /// </summary>
    public partial class SectionTiemChung : System.Web.UI.UserControl
    {
        private const byte StatusNew = 1;
        private const string DefaultAdminEmail = "tiemchung@tamduchearthospital.com";
        private static readonly Regex PhoneRegex = new Regex(@"^[0-9+\s().-]{8,20}$", RegexOptions.Compiled);

        protected void Page_Load(object sender, EventArgs e)
        {
            if (!IsPostBack)
            {
                pnlRegisterMessage.CssClass = "register-message register-msg-hidden";
            }
        }

        protected void btnSubmitRegister_Click(object sender, EventArgs e)
        {
            string fullName = SanitizeInput(txtFullName.Text, 250);
            string phone = SanitizeInput(txtPhone.Text, 20);
            string email = SanitizeInput(txtEmail.Text.Trim(), 250);
            string message = SanitizeInput(txtMessage.Text, 2000);

            if (string.IsNullOrWhiteSpace(fullName))
            {
                ShowRegisterMessage("Vui lòng nhập họ và tên.", false);
                return;
            }

            if (string.IsNullOrWhiteSpace(phone))
            {
                ShowRegisterMessage("Vui lòng nhập số điện thoại.", false);
                return;
            }

            if (!IsValidPhone(phone))
            {
                ShowRegisterMessage("Số điện thoại không hợp lệ.", false);
                return;
            }

            if (!string.IsNullOrWhiteSpace(email) && !IsValidEmail(email))
            {
                ShowRegisterMessage("Email không hợp lệ.", false);
                return;
            }

            INFO_TiemChungRegister obj = new INFO_TiemChungRegister();
            obj.FullName = fullName;
            obj.Phone = phone;
            obj.Email = string.IsNullOrWhiteSpace(email) ? null : email;
            obj.Message = string.IsNullOrWhiteSpace(message) ? null : message;
            obj.Status = StatusNew;
            obj.ClientIP = GetClientIP();

            if (!obj.Add() || obj.TiemChungRegisterID == null || obj.TiemChungRegisterID.Value <= 0)
            {
                ShowRegisterMessage("Không thể lưu thông tin đăng ký. Vui lòng thử lại sau.", false);
                return;
            }

            bool adminMailSent = false;
            bool customerMailSent = false;

            try
            {
                SendAdminEmail(fullName, phone, email, message, obj.TiemChungRegisterID.Value);
                adminMailSent = true;
            }
            catch
            {
                adminMailSent = false;
            }

            if (!string.IsNullOrWhiteSpace(email))
            {
                try
                {
                    SendCustomerEmail(email, fullName, phone, message);
                    customerMailSent = true;
                }
                catch
                {
                    customerMailSent = false;
                }
            }

            if (adminMailSent && (string.IsNullOrWhiteSpace(email) || customerMailSent))
            {
                ShowRegisterMessage("Cảm ơn Quý khách. Tâm Đức đã tiếp nhận yêu cầu tư vấn tiêm chủng và sẽ liên hệ sớm.", true);
            }
            else if (adminMailSent || customerMailSent)
            {
                ShowRegisterMessage("Đăng ký đã được lưu. Tuy nhiên hệ thống gửi email chưa hoàn tất — chúng tôi vẫn sẽ liên hệ Quý khách qua số điện thoại.", true);
            }
            else
            {
                ShowRegisterMessage("Đăng ký đã được lưu thành công. Tâm Đức sẽ liên hệ Quý khách trong thời gian sớm nhất.", true);
            }

            ClearRegisterForm();
            updRegister.Update();
        }

        private void SendAdminEmail(string fullName, string phone, string email, string message, int registerId)
        {
            string adminEmail = GetAdminEmail();
            string subject = string.Format("[Tiêm chủng] Đăng ký tư vấn #{0} - {1}", registerId, fullName);
            string body = BuildRegisterMailBody(fullName, phone, email, message, registerId);

            using (MailMessage mail = BuildHtmlMail(adminEmail, subject, body))
            {
                SendMailMessage(mail);
            }
        }

        private void SendCustomerEmail(string toEmail, string fullName, string phone, string message)
        {
            string subject = "[Bệnh viện Tim Tâm Đức] Đã tiếp nhận yêu cầu tư vấn tiêm chủng";
            StringBuilder sb = new StringBuilder();
            sb.Append("<p>Kính gửi <strong>").Append(Server.HtmlEncode(fullName)).Append("</strong>,</p>");
            sb.Append("<p>Bệnh viện Tim Tâm Đức đã tiếp nhận yêu cầu tư vấn tiêm chủng của Quý khách.</p>");
            sb.Append("<p>Đội ngũ Phòng Tiêm Chủng sẽ liên hệ trong thời gian sớm nhất qua số điện thoại Quý khách đã cung cấp.</p>");
            sb.Append("<hr />");
            sb.Append(BuildRegisterMailBody(fullName, phone, toEmail, message, null));
            sb.Append("<p>Hotline tư vấn tiêm chủng: <strong>(028) 3873 3026</strong></p>");
            sb.Append("<p>Trân trọng,<br />Bệnh viện Tim Tâm Đức</p>");

            using (MailMessage mail = BuildHtmlMail(toEmail, subject, sb.ToString()))
            {
                SendMailMessage(mail);
            }
        }

        private string BuildRegisterMailBody(string fullName, string phone, string email, string message, int? registerId)
        {
            StringBuilder sb = new StringBuilder();
            sb.Append("<table border='0' cellpadding='4' cellspacing='0' style='font-family:Arial,sans-serif;font-size:14px;'>");
            if (registerId.HasValue)
            {
                sb.Append("<tr><td><strong>Mã đăng ký:</strong></td><td>#").Append(registerId.Value).Append("</td></tr>");
            }
            sb.Append("<tr><td><strong>Họ tên:</strong></td><td>").Append(Server.HtmlEncode(fullName)).Append("</td></tr>");
            sb.Append("<tr><td><strong>Số điện thoại:</strong></td><td>").Append(Server.HtmlEncode(phone)).Append("</td></tr>");
            sb.Append("<tr><td><strong>Email:</strong></td><td>").Append(Server.HtmlEncode(string.IsNullOrWhiteSpace(email) ? "(Không có)" : email)).Append("</td></tr>");
            sb.Append("<tr><td valign='top'><strong>Nội dung:</strong></td><td>").Append(Server.HtmlEncode(string.IsNullOrWhiteSpace(message) ? "(Không có)" : message).Replace("\n", "<br />")).Append("</td></tr>");
            sb.Append("</table>");
            return sb.ToString();
        }

        private static MailMessage BuildHtmlMail(string toEmail, string subject, string htmlBody)
        {
            MailMessage message = new MailMessage();
            message.To.Add(new MailAddress(toEmail));
            message.Subject = subject;
            message.SubjectEncoding = Encoding.UTF8;
            message.Body = htmlBody;
            message.BodyEncoding = Encoding.UTF8;
            message.IsBodyHtml = true;
            message.Priority = MailPriority.High;
            return message;
        }

        private static void SendMailMessage(MailMessage message)
        {
            using (SmtpClient smtp = new SmtpClient())
            {
                smtp.Send(message);
            }
        }

        private string GetAdminEmail()
        {
            string configured = ConfigurationManager.AppSettings["TiemChung_AdminEmail"];
            if (!string.IsNullOrWhiteSpace(configured))
            {
                return configured.Trim();
            }
            return DefaultAdminEmail;
        }

        private string GetClientIP()
        {
            string ip = Request.ServerVariables["HTTP_X_FORWARDED_FOR"];
            if (!string.IsNullOrWhiteSpace(ip))
            {
                int comma = ip.IndexOf(',');
                if (comma > 0)
                {
                    ip = ip.Substring(0, comma);
                }
                return ip.Trim();
            }
            return Request.UserHostAddress;
        }

        private static string SanitizeInput(string value, int maxLength)
        {
            if (string.IsNullOrEmpty(value))
            {
                return string.Empty;
            }
            value = value.Trim();
            if (value.Length > maxLength)
            {
                value = value.Substring(0, maxLength);
            }
            return value;
        }

        private static bool IsValidPhone(string phone)
        {
            if (string.IsNullOrWhiteSpace(phone))
            {
                return false;
            }
            return PhoneRegex.IsMatch(phone.Trim());
        }

        private static bool IsValidEmail(string email)
        {
            if (string.IsNullOrWhiteSpace(email))
            {
                return false;
            }
            try
            {
                MailAddress addr = new MailAddress(email);
                return addr.Address.Equals(email, StringComparison.OrdinalIgnoreCase);
            }
            catch
            {
                return false;
            }
        }

        private void ShowRegisterMessage(string text, bool isSuccess)
        {
            pnlRegisterMessage.CssClass = "register-message";
            litRegisterMessage.Text = string.Format(
                "<p class=\"{0}\">{1}</p>",
                isSuccess ? "register-msg-success" : "register-msg-error",
                Server.HtmlEncode(text));
        }

        private void ClearRegisterForm()
        {
            txtFullName.Text = string.Empty;
            txtPhone.Text = string.Empty;
            txtEmail.Text = string.Empty;
            txtMessage.Text = string.Empty;
        }
    }
}

