    sb.Append("<tr><td style=\"background:linear-gradient(135deg,#0D7A3E 0%,#065A2B 100%);padding:28px 32px;\">");
    sb.Append("<div style=\"font-size:12px;font-weight:700;letter-spacing:1.2px;text-transform:uppercase;color:rgba(255,255,255,0.82);margin-bottom:8px;\">Bệnh viện Tim Tâm Đức</div>");
