    sb.Append("</td></tr>");

    sb.Append("<tr><td style=\"padding:24px 32px 0 32px;\">");
    sb.Append("<span style=\"display:inline-block;background-color:#E8F5EE;color:#0D7A3E;font-size:12px;font-weight:700;letter-spacing:0.6px;text-transform:uppercase;padding:7px 12px;border-radius:999px;\">");
