private string GetAdminEmail()
{
    string configured = ConfigurationManager.AppSettings["TiemChung_AdminEmail"];
    if (!string.IsNullOrWhiteSpace(configured))
    {
        return configured.Trim();
    }
    return DefaultAdminEmail;
}

